import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
is_strong_password = target.is_strong_password

def test_is_strong_password_valid():
    assert is_strong_password("Abc1234!") == True

def test_is_strong_password_too_short():
    assert is_strong_password("Abc1!") == False

def test_is_strong_password_no_upper():
    assert is_strong_password("abc1234!") == False

def test_is_strong_password_no_lower():
    assert is_strong_password("ABC1234!") == False

def test_is_strong_password_no_digit():
    assert is_strong_password("Abcdefg!") == False

def test_is_strong_password_no_symbol():
    assert is_strong_password("Abc12345") == False

def test_is_strong_password_type_error():
    with pytest.raises(TypeError):
        is_strong_password(123)

